Tool response:
Tool: exercise_stock_options
Description: Exercise Stock Options
Parameters:
    {
      "type": "object",
      "properties": {
        "employee_id": {
          "type": "integer",
          "title": "Employee Id"
        },
        "stock_grant_id": {
          "type": "integer",
          "title": "Stock Grant Id"
        },
        "options_exercised": {
          "type": "integer",
          "title": "Options Exercised"
        },
        "payment_method": {
          "type": "string",
          "title": "Payment Method",
          "description": "Payment method used for exercise (wire, ach, check, credit_card, other)"
        },
        "payment_reference": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Payment Reference"
        }
      },
      "required": [
        "employee_id",
        "stock_grant_id",
        "options_exercised",
        "payment_method"
      ]
    }
